import type { DwgDictionaryBody,DwgTableControlBody,DwgXRecordBody } from "../../../🟦️.ts";
import { DwgProjection,dwgInteger,dwgBoolean as B,dwgUnsignedWords as H,dwgOptionalWords as O,type DwgCell } from "../🔢️number/🟦️.ts";
import { DwgReader,dwgWord,dwgBoolean,dwgOptionalUnsigned,dwgFullUnsigned } from "../🫳️reader/🟦️.ts";
import { dwgProjectValues,dwgReconstructValues,dwgRequireNull } from "../🏷️xrecord/🟦️.ts";

export async function dwgProjectDictionary(p:DwgProjection,id:bigint,v:DwgDictionaryBody):Promise<void>{
  await p.insert("dwg_dictionary",[dwgInteger(v.cloningFlag,0,65535),B(v.hardOwner),...O(v.defaultEntryHandle)],id);
  for(const[index,entry]of v.entries.entries())await p.insert("dwg_dictionary_entry",[id,BigInt(index),entry.name,...H(entry.handle)]);
}
export async function dwgReconstructDictionary(reader:DwgReader,id:bigint):Promise<DwgDictionaryBody>{
  const row=await reader.component("dwg_dictionary",id);const entries:DwgDictionaryBody["entries"]=[];
  for(const entry of await reader.list("dwg_dictionary_entry",1,id,2))entries.push({name:entry.text(3),handle:dwgFullUnsigned(entry,4,5)});
  return{entries,cloningFlag:dwgWord(row,1),hardOwner:dwgBoolean(row,2),defaultEntryHandle:dwgOptionalUnsigned(row,3,4)};
}
export async function dwgProjectControl(p:DwgProjection,id:bigint,v:DwgTableControlBody):Promise<void>{
  let kind:string;let model:readonly DwgCell[]=[null,null],paper:readonly DwgCell[]=[null,null],byBlock:readonly DwgCell[]=[null,null],byLayer:readonly DwgCell[]=[null,null];
  switch(v.kind){
    case"block":kind="block";model=O(v.value.modelSpaceHandle);paper=O(v.value.paperSpaceHandle);break;
    case"linetype":kind="linetype";byBlock=H(v.value.byBlockHandle);byLayer=H(v.value.byLayerHandle);break;
    case"layer":kind="layer";break;case"textStyle":kind="text_style";break;case"view":kind="view";break;case"ucs":kind="ucs";break;
    case"viewport":kind="viewport";break;case"registeredApplication":kind="registered_application";break;case"dimensionStyle":kind="dimension_style";break;
    default:throw new Error("DWG table-control kind is unknown");
  }
  await p.insert("dwg_table_control",[kind,...model,...paper,...byBlock,...byLayer],id);
  for(const[index,value]of v.value.entryHandles.entries())await p.insert("dwg_table_control_entry",[id,BigInt(index),...O(value.handle)]);
  if(v.kind==="dimensionStyle")for(const[index,handle]of v.value.additionalHandles.entries())await p.insert("dwg_dimension_style_control_additional_handle",[id,BigInt(index),...H(handle)]);
}
export async function dwgReconstructControl(reader:DwgReader,id:bigint):Promise<DwgTableControlBody>{
  const row=await reader.component("dwg_table_control",id),entryHandles:DwgTableControlBody["value"]["entryHandles"]=[];
  for(const entry of await reader.list("dwg_table_control_entry",1,id,2))entryHandles.push({handle:dwgOptionalUnsigned(entry,3,4)});
  const additional=await reader.list("dwg_dimension_style_control_additional_handle",1,id,2),kind=row.text(1);
  if(kind!=="dimension_style"&&additional.length!==0)throw new Error("DWG additional dimension-style handles have the wrong control kind");
  switch(kind){
    case"block":dwgRequireNull(row,[6,7,8,9]);return{kind:"block",value:{entryHandles,modelSpaceHandle:dwgOptionalUnsigned(row,2,3),paperSpaceHandle:dwgOptionalUnsigned(row,4,5)}};
    case"linetype":dwgRequireNull(row,[2,3,4,5]);return{kind:"linetype",value:{entryHandles,byBlockHandle:dwgFullUnsigned(row,6,7),byLayerHandle:dwgFullUnsigned(row,8,9)}};
    case"dimension_style":dwgRequireNull(row,[2,3,4,5,6,7,8,9]);return{kind:"dimensionStyle",value:{entryHandles,additionalHandles:additional.map(value=>dwgFullUnsigned(value,3,4))}};
    case"layer":dwgRequireNull(row,[2,3,4,5,6,7,8,9]);return{kind:"layer",value:{entryHandles}};
    case"text_style":dwgRequireNull(row,[2,3,4,5,6,7,8,9]);return{kind:"textStyle",value:{entryHandles}};
    case"view":dwgRequireNull(row,[2,3,4,5,6,7,8,9]);return{kind:"view",value:{entryHandles}};
    case"ucs":dwgRequireNull(row,[2,3,4,5,6,7,8,9]);return{kind:"ucs",value:{entryHandles}};
    case"viewport":dwgRequireNull(row,[2,3,4,5,6,7,8,9]);return{kind:"viewport",value:{entryHandles}};
    case"registered_application":dwgRequireNull(row,[2,3,4,5,6,7,8,9]);return{kind:"registeredApplication",value:{entryHandles}};
    default:throw new Error("DWG table-control kind is unknown");
  }
}
export async function dwgProjectXRecord(p:DwgProjection,id:bigint,v:DwgXRecordBody):Promise<void>{
  await p.insert("dwg_xrecord",[dwgInteger(v.cloningFlag,0,65535)],id);await dwgProjectValues(p,undefined,id,v.values);
  for(const[index,value]of v.objectIdHandles.entries())await p.insert("dwg_xrecord_object_id_handle",[id,BigInt(index),...H(value)]);
}
export async function dwgReconstructXRecord(reader:DwgReader,id:bigint):Promise<DwgXRecordBody>{
  const row=await reader.component("dwg_xrecord",id);const values=await dwgReconstructValues(reader,undefined,id);
  const objectIdHandles=(await reader.list("dwg_xrecord_object_id_handle",1,id,2)).map(value=>dwgFullUnsigned(value,3,4));
  return{values,objectIdHandles,cloningFlag:dwgWord(row,1)};
}
